(()=>{'use strict';
let homeData=null,stagesData=null,loading=null;
const HOME_URL='ffws-br-2026-s2/home-results.json';
const STAGES_URL='ffws-br-2026-s2/stages.json';
const PLAYER_STATS_URL='ffws-br-2026-s2/player-stats.json';
const PLAYERS_URL='ffws-br-2026-s2/players.json';
const LIVE_PATH='ffwsLive/2026-s2';
const SECOND_PHASE_SEED=[
  {team:'LOS',sourcePosition:1,bonus:50},{team:'LOUD SNICKERS',sourcePosition:2,bonus:42},
  {team:'FLUXO W7M',sourcePosition:3,bonus:35},{team:'INTZ',sourcePosition:4,bonus:29},
  {team:'TEAM SOLID',sourcePosition:5,bonus:24},{team:'RISE GAMING',sourcePosition:6,bonus:19},
  {team:'ALPHA7',sourcePosition:7,bonus:15},{team:'RUSH GAMING',sourcePosition:8,bonus:11},
  {team:'INFLUENCE RAGE',sourcePosition:9,bonus:8},{team:'CPT VOX',sourcePosition:10,bonus:5},
  {team:'AFROGAMES',sourcePosition:11,bonus:2},{team:'SX TET',sourcePosition:12,bonus:0}
];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/gi,'').toUpperCase();
const pkey=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const num=v=>Number(v)||0;
const vals=v=>Array.isArray(v)?v.filter(Boolean):Object.values(v||{}).filter(Boolean);
const shortTeam=name=>({
  'LOUD SNICKERS':'LOUD','FLUXO W7M':'FX','RISE GAMING':'RISE','RUSH GAMING':'RUSH',
  'TEAM SOLID':'TS','AFROGAMES':'AFG','CIVIS':'CTZ','LOOPS':'LPS','SX TET':'SX','CPT VOX':'CPT','ALPHA7':'A7',
  'INFLUENCE RAGE':'INF','FURY UNITED':'FURY','AXS FUSION':'AXS','HAWK GAMING':'HAWK'
}[String(name||'').toUpperCase()]||String(name||''));
const fmt=n=>num(n).toLocaleString('pt-BR');
const slug=(v,sep='')=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,sep).replace(new RegExp(`^${sep||'\\s'}+|${sep||'\\s'}+$`,'g'),'');
const teamThumb=team=>`home-assets/teams/${slug(team,'-')}.webp`;
const playerThumb=name=>`home-assets/players/${slug(name)}.webp`;
const playerFull=name=>`player-photos/s2/${slug(name)}.webp`;
function playerImg(name){return `<img class="home-rank-avatar" src="${esc(playerThumb(name))}" alt="" loading="lazy" decoding="async" width="32" height="32" onerror="if(this.dataset.fb){this.onerror=null;this.src='silhueta.webp'}else{this.dataset.fb='1';this.src='${esc(playerFull(name))}'}">`}
function teamImg(team){return `<img class="home-rank-team-logo" src="${esc(teamThumb(team))}" alt="" loading="lazy" decoding="async" width="30" height="30" onerror="this.onerror=null;this.src='escudo.webp'">`}
async function getJson(url){const join=url.includes('?')?'&':'?';const r=await fetch(`${url}${join}v=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}
async function getLive(){const base=String(window.CFF_CONFIG?.firebase?.databaseURL||'').replace(/\/$/,'');if(!base)return null;const r=await fetch(`${base}/${LIVE_PATH}.json?v=${Date.now()}`,{cache:'no-store'});if(!r.ok)return null;return r.json()}
function flattenLive(stage){const out=[];const days=stage?.drops||{};Object.keys(days).sort((a,b)=>num(a)-num(b)).forEach(day=>{const drops=days[day]||{};Object.keys(drops).sort((a,b)=>num(a)-num(b)).forEach(drop=>{const item=drops[drop];if(item)out.push({...item,day:num(item.day||day),drop:num(item.drop||drop)})})});return out}
function applyLiveStages(stages,live){
  if(!stages||!live?.segundaFase)return stages||{};
  const drops=flattenLive(live.segundaFase);if(!drops.length)return stages;
  const phase=stages.segundaFase||(stages.segundaFase={});
  phase.rounds=drops.map(item=>({round:item.day,number:item.drop,drop:item.drop,map:item.map||'',results:vals(item.teams).map(r=>({team:r.team,position:num(r.position),placementPoints:num(r.placementPoints),kills:num(r.kills),points:num(r.points),booyah:num(r.booyah)}))}));
  phase.finished=drops.length>=36;return stages;
}
function mergeLiveStats(stats,live){
  if(!stats||typeof stats!=='object')stats={players:{}};if(!stats.players)stats.players={};
  const agg=new Map();
  ['segundaFase','final'].forEach(stageKey=>flattenLive(live?.[stageKey]).forEach(drop=>vals(drop.players).forEach(p=>{const k=pkey(p.name);if(!k)return;if(!agg.has(k))agg.set(k,{name:p.name,team:p.team,stages:{},days:new Map()});const a=agg.get(k);a.name=p.name||a.name;a.team=p.team||a.team;if(!a.stages[stageKey])a.stages[stageKey]={kills:0,damage:0,assists:0,matches:0,mvp:0};const s=a.stages[stageKey];s.kills+=num(p.kills);s.damage+=num(p.damage);s.assists+=num(p.assists);s.matches+=1;s.mvp+=num(p.mvp);const dk=`${stageKey}:${drop.day}`;a.days.set(dk,(a.days.get(dk)||0)+num(p.kills))})));
  const byName=new Map(Object.entries(stats.players).map(([key,p])=>[pkey(p?.name||key),key]));
  agg.forEach((a,k)=>{const key=byName.get(k)||k;const r=stats.players[key]||{name:a.name,team:a.team,kills:0,damage:0,assists:0,matches:0,mvp:0,record:0,stages:{}};r.stages=r.stages||{};Object.entries(a.stages).forEach(([stageKey,next])=>{const old=r.stages[stageKey]||{};r.kills=num(r.kills)-num(old.kills)+num(next.kills);r.damage=num(r.damage)-num(old.damage)+num(next.damage);r.assists=num(r.assists)-num(old.assists)+num(next.assists);r.matches=num(r.matches)-num(old.matches)+num(next.matches);r.mvp=num(r.mvp)-num(old.mvp)+num(next.mvp);r.stages[stageKey]={...next}});r.name=a.name||r.name;r.team=a.team||r.team;r.record=Math.max(num(r.record),0,...a.days.values());stats.players[key]=r});
  return stats;
}
function applyStatsToHome(home,stats){const records=Object.values(stats?.players||{});const rank=field=>records.filter(r=>num(r[field])>0).sort((a,b)=>num(b[field])-num(a[field])||String(a.name||'').localeCompare(String(b.name||''),'pt-BR')).slice(0,6).map(r=>({player:r.name,name:r.name,team:r.team,kills:num(r.kills),damage:num(r.damage),assists:num(r.assists),matches:num(r.matches),mvp:num(r.mvp)}));home.rankings={...(home.rankings||{}),kills:rank('kills'),damage:rank('damage'),assists:rank('assists')};home.players=home.rankings.kills;return home}
function homeSelectionMeta(payload,name,team){
  const list=Array.isArray(payload?.players)?payload.players:[],n=pkey(name),t=norm(team);
  return list.find(p=>norm(p?.team)===t&&[p?.name,p?.sourceName,...(p?.aliases||[])].some(a=>pkey(a)===n))
    ||list.find(p=>[p?.name,p?.sourceName,...(p?.aliases||[])].some(a=>pkey(a)===n))
    ||null;
}
function homeSelectionRole(row){
  const raw=String(row?.roleShort||row?.role||row?.meta?.roleShort||row?.meta?.role||'RUSH').toUpperCase();
  if(raw.includes('GRAN'))return'GRAN';
  if(raw.includes('SUP'))return'SUP';
  if(raw==='3'||raw.includes('3º'))return'3';
  return'RUSH';
}
function latestSecondPhaseSelection(payload){
  const entries=(Array.isArray(payload?.entries)?payload.entries:[]).filter(e=>norm(e?.stage||e?.etapa)==='SEGUNDAFASE');
  if(!entries.length)return null;
  const days=[...new Set(entries.map(e=>num(e?.day||e?.round)).filter(Boolean))].sort((a,b)=>a-b);
  const latestDay=days[days.length-1]||0;if(!latestDay)return null;
  const week=Math.max(1,Math.min(3,Math.ceil(latestDay/2))),block=[week*2-1,week*2],availableDays=block.filter(day=>days.includes(day));
  const agg=new Map();
  entries.filter(e=>block.includes(num(e?.day||e?.round))).forEach(e=>{
    const name=e?.name||e?.player||e?.jogador,sourceTeam=e?.team||e?.equipe||'';if(!name)return;
    const meta=homeSelectionMeta(payload,name,sourceTeam),team=meta?.team||sourceTeam;
    const key=`${pkey(name)}__${norm(team)}`;
    if(!agg.has(key))agg.set(key,{player:meta?.name||name,name:meta?.name||name,team,meta,roleShort:e?.roleShort||meta?.roleShort||'',role:e?.role||meta?.role||'',kills:0,damage:0,assists:0,matches:0});
    const row=agg.get(key);row.kills+=num(e?.kills??e?.abates);row.damage+=num(e?.damage??e?.dano);row.assists+=num(e?.assists??e?.assistencias);row.matches+=num(e?.matches??e?.quedas)||1;
  });
  const rows=[...agg.values()].sort((a,b)=>b.kills-a.kills||b.damage-a.damage||b.assists-a.assists);
  const used=new Set(),take=(roles,count)=>rows.filter(row=>!used.has(row)&&roles.includes(homeSelectionRole(row))).slice(0,count).map(row=>(used.add(row),row));
  let selected=[...take(['RUSH','3'],2),...take(['GRAN'],1),...take(['SUP'],1)];
  if(selected.length<4)selected=selected.concat(rows.filter(row=>!used.has(row)).slice(0,4-selected.length));
  selected=selected.map(row=>({...row,roleShort:homeSelectionRole(row)}));
  return selected.length?{stage:'segundaFase',week,days:availableDays,players:selected}:null;
}
async function load(){
  if(homeData&&stagesData)return {home:homeData,stages:stagesData};
  if(loading)return loading;
  loading=Promise.allSettled([getJson(HOME_URL),getJson(STAGES_URL),getJson(PLAYER_STATS_URL),getJson(PLAYERS_URL),getLive()]).then(results=>{
    homeData=results[0].status==='fulfilled'?results[0].value:{teams:[],players:[],rankings:{kills:[],damage:[],assists:[]},weeklySelection:null};
    stagesData=results[1].status==='fulfilled'?results[1].value:{};
    let stats=results[2].status==='fulfilled'?results[2].value:{players:{}};
    const playersPayload=results[3].status==='fulfilled'?results[3].value:null;
    const live=results[4].status==='fulfilled'?results[4].value:null;
    if(live){stagesData=applyLiveStages(stagesData,live);stats=mergeLiveStats(stats,live);homeData=applyStatsToHome(homeData,stats)}
    const liveWeekly=latestSecondPhaseSelection(playersPayload);if(liveWeekly)homeData.weeklySelection=liveWeekly;
    return {home:homeData,stages:stagesData};
  }).finally(()=>loading=null);
  return loading;
}
function placeholder(text,cols=5){return `<tr><td colspan="${cols}" class="home-rank-placeholder">${esc(text)}</td></tr>`}
function secondPhaseRows(stages){
  const phase=stages?.segundaFase||{};
  const rows=SECOND_PHASE_SEED.map(seed=>({team:seed.team,position:seed.sourcePosition,sourcePosition:seed.sourcePosition,bonus:seed.bonus,points:seed.bonus,booyahs:0,kills:0,placementPoints:0,matches:0}));
  const byTeam=new Map(rows.map(row=>[norm(row.team),row]));
  const rounds=Array.isArray(phase.rounds)?phase.rounds:[];
  let hasRoundResults=false;
  rounds.forEach(round=>(Array.isArray(round?.results)?round.results:(Array.isArray(round?.rows)?round.rows:[])).forEach(result=>{
    const row=byTeam.get(norm(result?.team||result?.equipe));if(!row)return;hasRoundResults=true;
    row.points+=num(result.points??result.pontos??(num(result.placementPoints)+num(result.kills)));
    row.booyahs+=num(result.booyah??result.booyahs??(num(result.position||result.posicao)===1?1:0));
    row.kills+=num(result.kills??result.abates);row.placementPoints+=num(result.placementPoints??result.pontosColocacao??result.pp);row.matches+=num(result.matches||1);
  }));
  if(!hasRoundResults){
    const currentRows=Array.isArray(phase.rows)?phase.rows:[];
    const meaningfulRows=currentRows.filter(row=>byTeam.has(norm(row?.team))&&num(row.matches)>0);
    if(meaningfulRows.length){
      meaningfulRows.forEach(current=>{
        const row=byTeam.get(norm(current.team));if(!row)return;
        const rawPoints=num(current.points);const bonus=num(current.bonus??row.bonus);
        row.bonus=bonus;row.points=rawPoints>=bonus?rawPoints:rawPoints+bonus;
        row.booyahs=num(current.booyahs??current.booyah);row.kills=num(current.kills);row.placementPoints=num(current.placementPoints);row.matches=num(current.matches);
      });
      hasRoundResults=true;
    }
  }
  if(hasRoundResults){rows.sort((a,b)=>b.points-a.points||b.booyahs-a.booyahs||b.kills-a.kills||a.team.localeCompare(b.team,'pt-BR'));rows.forEach((row,i)=>row.position=i+1)}
  return rows;
}
function teamRows(rows){return rows.length?rows.slice(0,6).map((r,i)=>{
  const pos=num(r.position)||i+1;const world=pos<=2;const meta=`${num(r.matches)} Q`;
  return `<tr class="${world?'home-rank-world-row':''}"><td class="home-rank-pos">${pos}</td><td class="home-rank-media"><a href="equipe.html?time=${encodeURIComponent(r.team)}" aria-label="${esc(shortTeam(r.team))}">${teamImg(r.team)}</a></td><td class="home-rank-main"><a class="home-rank-identity" href="equipe.html?time=${encodeURIComponent(r.team)}"><span><b>${esc(shortTeam(r.team))}</b><small>${esc(meta)}</small></span></a></td><td class="home-rank-number home-rank-points">${fmt(r.points)}</td><td class="home-rank-number">${fmt(r.kills)}</td></tr>`;
}).join(''):placeholder('Segunda Fase ainda sem classificação.')}
function playerRows(rows,metric){return rows.length?rows.slice(0,6).map((r,i)=>{const name=r.player||r.name||'';const href=`jogador.html?jogador=${encodeURIComponent(name)}&time=${encodeURIComponent(r.team||'')}`;return `<tr><td class="home-rank-pos">${i+1}</td><td class="home-rank-media"><a href="${href}" aria-label="${esc(name)}">${playerImg(name)}</a></td><td class="home-rank-main"><a class="home-rank-identity" href="${href}"><span><b>${esc(name)}</b><small>${esc(shortTeam(r.team||''))}</small></span></a></td><td class="home-rank-number">${fmt(r[metric])}</td><td class="home-rank-number home-rank-matches">${num(r.matches)}</td></tr>`}).join(''):placeholder('Ranking disponível após as primeiras quedas.')}
function renderWeekly(selection){const root=document.getElementById('home-weekly-selection-list'),meta=document.getElementById('home-weekly-selection-meta');if(!root)return;const rows=Array.isArray(selection?.players)?selection.players:[];if(meta){const days=Array.isArray(selection?.days)?selection.days:[],phase=selection?.stage==='segundaFase'?'2ª FASE • ':'';meta.textContent=rows.length?`${phase}SEMANA ${selection.week||''}${days.length?` • DIAS ${days.join(' E ')}`:''}`:'EM BREVE'}if(!rows.length){root.innerHTML='<div class="home-weekly-empty">Seleção disponível após as rodadas da semana.</div>';return}root.innerHTML=rows.slice(0,4).map(r=>{const name=r.player||r.name||'';return `<a class="home-weekly-player" href="jogador.html?jogador=${encodeURIComponent(name)}&time=${encodeURIComponent(r.team||'')}">${playerImg(name)}<span class="home-weekly-player-name"><b>${esc(name)}</b><small>${esc(shortTeam(r.team||''))} • ${esc(r.roleShort||'')}</small></span><span class="home-weekly-stat"><small>K</small><b>${fmt(r.kills)}</b></span><span class="home-weekly-stat home-weekly-dmg"><small>DMG</small><b>${fmt(r.damage)}</b></span></a>`}).join('')}
function tuneTeamWidget(){
  const tbody=document.getElementById('home-tbody-teams');const widget=tbody?.closest('.home-widget');if(!widget)return;
  const title=widget.querySelector('h3');if(title)title.textContent='🌎 Top 6 Segunda Fase';
  const link=widget.querySelector('.home-widget-link-btn');if(link){link.textContent='Ver Segunda Fase completa →';link.onclick=()=>typeof window.navigate==='function'?window.navigate('ffws-br-s2-segunda-fase'):location.assign('#ffws-br-s2-segunda-fase')}
}
function render(payload){const home=payload?.home||{};const rankings=home.rankings||{};const kills=rankings.kills||home.players||[];const teams=secondPhaseRows(payload?.stages||{});[['home-tbody-teams',teamRows(teams)],['home-tbody-players',playerRows(kills,'kills')],['home-tbody-damage',playerRows(rankings.damage||[],'damage')],['home-tbody-assists',playerRows(rankings.assists||[],'assists')]].forEach(([id,html])=>{const el=document.getElementById(id);if(el)el.innerHTML=html});tuneTeamWidget();renderWeekly(home.weeklySelection)}
window.cffHomeRenderFinalStats=function(){homeData=null;stagesData=null;load().then(render);return true};
const boot=()=>load().then(render).catch(()=>{});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();